function Field({label,name,type='text',required=false,children,...props}:{label:string;name:string;type?:string;required?:boolean;children?:ReactNode;[key:string]:any}){return <label className="field"><span>{label}{required&&<b> *</b>}</span>{children?<select name={name} required={required} {...props}>{children}</select>:<input name={name} type={type} required={required} {...props}/>}</label>}
