 async function login(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);await safe(async()=>{await loginWithIdentifier(String(f.get('identifier')),String(f.get('password')))});setBusy(false)}
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;const form=e.currentTarget;const p=Object.fromEntries(new FormData(form)) as Row;setBusy(true);if(p.extras_json){p.extras=JSON.parse(p.extras_json);delete p.extras_json;}const ok=await safe(async()=>{if(modal?.action==='purchase_edit'){
 const payload={purchase_id:modal.purchase.id,inventory_id:modal.item.id,model:String(p.model),storage:String(p.storage),color:String(p.color||''),imei_1:String(p.imei_1),imei_2:String(p.imei_2||''),serial_number:String(p.serial_number||''),battery_health:String(p.battery_health||''),pta_status:String(p.pta_status),purchase_price:String(p.purchase_price),condition_grade:String(p.condition_grade||''),warranty_notes:String(p.warranty_notes||'')};
 await updatePhonePurchase(payload);setModal(null);setNotice('Purchase updated. Seller details were not changed.');await refresh(true);return true;
}
if(modal?.action==='staff'){
 if(!navigator.onLine)throw Error('Internet is required to create or change staff login access.');
 if(!modal.item){
  const username=String(p.username||'').trim(),email=String(p.email||'').trim();if(!username&&!email)throw Error('Enter a username or email for this staff login.');await createStaffUser({email:email||undefined,password:String(p.password),username:username||undefined,full_name:String(p.full_name),role:String(p.role),is_active:String(p.is_active)!=='false',website_portal_access:String(p.website_portal_access)==='true'});
  setModal(null);setNotice('Staff login created. Supabase ID was assigned automatically.');await refresh(true);return true;
 }
 await updateStaffUser({user_id:modal.item.id,username:String(p.username||'').trim()||undefined,full_name:String(p.full_name),role:String(p.role),is_active:String(p.is_active)!=='false',website_portal_access:String(p.website_portal_access)==='true'});
 setModal(null);setNotice('Staff access updated.');await refresh(true);return true;
}const payload={...p,...modal?.payload,action:modal?.action};const photo=p.photo instanceof File&&p.photo.size?p.photo:undefined;delete payload.photo;const result=await act(payload,{photo,userId:session.user.id});setModal(null);setNotice(result?.offline?'Saved offline. It will sync automatically when internet returns.':'Saved to your store.');await refresh(true);setOfflineRows(await pendingDetails());return true});setBusy(false);return ok}
 async function changeRepair(item:Row,checked:boolean){if(busy)return;setBusy(true);await safe(async()=>{await act({action:'repair',inventory_id:item.id,repairing:checked});await refresh(true);setNotice(checked?'Phone marked as in repair.':'Phone returned to available stock.');});setBusy(false)}
 const exportData=async(rows:Row[],format:'csv'|'xlsx')=>safe(async()=>{await exportRows(page.replaceAll(' ','-'),rows,format);setNotice('Export ready.');});
 const showPhoto=async(s:Row)=>safe(async()=>{if(!s.photo_url)throw Error('No seller photo saved.');if(/^https:/.test(s.photo_url))throw Error('Legacy URL. Re-upload this photo to private storage.');const {data,error}=await db.storage.from('seller-photos').createSignedUrl(s.photo_url,60);if(error)throw error;setModal({action:'photo',title:s.full_name,url:data.signedUrl})});
 async function ask(text=question){if(!text.trim())return;setQuestion('');setChat(c=>[...c,{role:'user',text}]);if(import.meta.env.VITE_AI_SERVER_URL){try{const {data:{session:current}}=await db.auth.getSession();const response=await fetch(import.meta.env.VITE_AI_SERVER_URL.replace(/\/$/,'')+'/api/assistant',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+current?.access_token},body:JSON.stringify({question:text})});const result=await response.json();if(!response.ok)throw Error(result.detail||'AI request failed');setChat(c=>[...c,{role:'assistant',text:result.answer}]);}catch(e:any){setChat(c=>[...c,{role:'assistant',text:e.message}]);}return;}const q=text.toLowerCase();const dead=available.filter(i=>(Date.now()-new Date(i.created_at).getTime())/86400000>45);let answer='Try “customer dues”, “supplier dues”, “profit”, “cash flow”, “dead stock”, “restock”, “forecast”, or “business health”.';
 if(/profit|expense|balance|cash flow/.test(q)){answer=owner?`Revenue: ${money(sum(actualSales,'final_total')+manualImpact.income)}. Gross profit: ${money(gross)}. Expenses: ${money(sum(data.expenses,'amount'))}. Net profit: ${money(net)}. Book cash: ${money(accountBalance(data.accounts,'1000'))}. Use Reports for the balance sheet and cash movements.`:'Profit and financial reports are restricted to the owner.';}
 else if(/customer|receivable/.test(q))answer=`Receivables total ${money(totalReceivable)} across ${ledgerRows(data,'receivable').filter((r:Row)=>r.balance>0).length} outstanding entries. Open Receivables ledger for invoices and other balances.`;
 else if(/supplier|payable/.test(q))answer=manager?`Payables total ${money(totalPayable)}. Open Payables ledger to view purchases and other balances and record partial or full payments.`:'Supplier financial records require manager access.';
 else if(/dead|slow/.test(q))answer=dead.length?`${dead.length} phones have been in stock over 45 days: ${dead.map(i=>i.model+' ('+i.stock_code+')').join(', ')}. Consider checking market price and featuring these in your next content post.`:'No in-stock phones are older than the 45-day threshold.';
 else if(/restock|recommend|low stock|supplier|price/.test(q)){const counts=new Map<string,number>();data.saleItems.forEach((i:Row)=>counts.set(i.item_name,(counts.get(i.item_name)||0)+Number(i.quantity)));const rank=[...counts].sort((a,b)=>b[1]-a[1]);answer=rank.length?rank.slice(0,5).map(([model,n])=>`${model}: ${n} sold, ${available.filter(i=>i.model===model).length} on hand. ${available.filter(i=>i.model===model).length<2?'Review for reorder.':'Stock available.'}`).join('\n'):'No sales history yet. Restocking and pricing recommendations become more useful after actual sales are recorded.';}
 else if(/forecast|season/.test(q)){const days=new Set(data.sales.map((s:Row)=>localDay(s.sale_date))).size;answer=days<7?'Record sales on at least 7 different days before using a forecast. Seasonal demand needs longer history.':`Simple baseline estimate: ${money(sum(actualSales,'final_total')/Math.max(1,(Date.now()-Math.min(...data.sales.map((s:Row)=>new Date(s.sale_date).getTime())))/86400000)*30)} revenue over 30 days. This extrapolates average daily revenue, with no seasonal model or guarantee.`;}
 else if(/health|summary|stock/.test(q))answer=`${available.length} phones in stock; ${data.sales.length} sales recorded; ${money(totalReceivable)} receivable${manager?`; ${money(totalPayable)} payable`:''}. ${dead.length} phones exceed 45 days in stock.${owner?` Net profit is ${money(net)}.`:''}`;
 setChat(c=>[...c,{role:'assistant',text:answer}]);}
