 {data.profile&&page==='Dashboard'&&<><div className="metric-grid"><Metric label="Sales today" value={money(sum(todaySales,'final_total'))} foot={`${todaySales.length} invoices today`} icon={<Receipt/>}/><Metric label="Phones in stock" value={available.length.toString()} foot={`${inv.length} tracked phones`} icon={<Smartphone/>}/><Metric label="Receivables" value={money(totalReceivable)} foot="Outstanding receivables" icon={<Wallet/>}/><Metric label={owner?'Net profit':manager?'Payables':'Total revenue'} value={money(owner?net:manager?totalPayable:sum(actualSales,'final_total'))} foot={owner?'After recorded expenses':manager?'Outstanding payables':'All recorded sales'} icon={<TrendingUp/>}/></div><div className="dashboard-grid"><section className="panel revenue"><div className="panel-head"><div><h3>Revenue overview</h3><small>Your last 7 days of sales</small></div><span className="tag neutral">This week</span></div><h2>{money(sum(actualSales.filter((s:Row)=>new Date(s.sale_date).getTime()>Date.now()-7*86400000),'final_total'))}</h2><RevenueChart sales={actualSales}/></section><section className="panel stock-summary"><div className="panel-head"><h3>Inventory health</h3><Smartphone size={18}/></div><div className="stock-count"><b>{available.length}</b><span>phones ready to sell</span></div>{['in_stock','reserved','sold','repair'].map(s=><div className="stock-row" key={s}><span><i className={'status-dot '+s}/>{status(s)}</span><b>{inv.filter(i=>i.status===s).length}</b></div>)}<button className="text-button" onClick={()=>go('Inventory')}>View inventory<ArrowUpRight size={16}/></button></section></div><div className="dashboard-bottom"><section className="panel"><div className="panel-head"><div><h3>Latest stock</h3><small>A closer look at your newest phones</small></div><button className="text-button" onClick={()=>go('Inventory')}>View all<ChevronRight size={16}/></button></div>{inv.length?<DataTable headers={['Phone','IMEI','Status','Asking price']}>{activeInventory.slice(0,5).map(i=><tr key={i.id}><td><div className="phone-cell"><span className="phone-icon"><Smartphone size={20}/></span><div><b>{i.model}</b><small>{i.storage} · {status(i.pta_status)}</small></div></div></td><td className="mono">{i.imei_1||i.serial_number||'—'}</td><td><Tag value={i.status}/></td><td>{money(i.default_sale_price)}</td></tr>)}</DataTable>:<Empty/>}</section><section className="panel insight"><span className="ai-symbol"><Sparkles/></span><h3>On your radar</h3><p>{available.filter(i=>(Date.now()-new Date(i.created_at).getTime())>45*86400000).length} phones have been in stock for over 45 days.</p><div className="insight-rule"/><p>{data.sales.filter((s:Row)=>customerDue(s)>0).length} invoices have an outstanding balance.</p><button className="text-button" onClick={()=>go('Business assistant')}>Ask your assistant<ArrowUpRight size={16}/></button></section></div><div className="workflow"><span><ShieldCheck size={17}/>Your records stay connected.</span><p>Inventory updates feed your website catalog. A sale automatically removes the phone from public stock.</p></div></>}
