 {data.profile&&page==='Daily closing'&&owner&&<><div className="daily-banner"><div><span className="eyebrow">DAILY CASH DESK</span><h2>{data.sessions.some((s:Row)=>s.business_date===today&&!s.closed_at)?'Your day is open.':'Ready for your next day?'}</h2><p>Count the cash drawer at opening and closing. Opening counts do not create capital or revenue.</p></div>{!data.sessions.some((s:Row)=>s.business_date===today||!s.closed_at)&&<button className="primary" onClick={()=>setModal({action:'open_day',title:'Open the day'})}><Plus size={17}/>Open today</button>}</div><section className="panel">{data.sessions.length?<DataTable headers={['Business date','Opening','Expected','Counted','Variance','Status','Action']}>{data.sessions.map((s:Row)=><tr key={s.id}><td><b>{s.business_date}</b></td><td>{money(s.opening_cash)}</td><td>{s.expected_cash==null?'—':money(s.expected_cash)}</td><td>{s.counted_cash==null?'—':money(s.counted_cash)}</td><td className={Number(s.variance)<0?'negative':''}>{s.variance==null?'—':money(s.variance)}</td><td><Tag value={s.closed_at?'closed':'open'}/></td><td>{!s.closed_at&&<button onClick={()=>setModal({action:'close_day',title:'Close cash drawer',payload:{session_id:s.id}})}>Close day</button>}</td></tr>)}</DataTable>:<Empty text="Open your first day with the counted cash in your drawer."/>}</section></>}
 {data.profile&&page==='Reports'&&owner&&<section className="panel"><div className="report-tools"><select value={report} onChange={e=>setReport(e.target.value)}>{['Profit & loss','Invoice profit','Profit per IMEI','Trial balance','Balance sheet','Cash flow','Stock report','Product analytics','Supplier analytics','Audit log'].map(r=><option key={r}>{r}</option>)}</select><label>From<input type="date" value={from} onChange={e=>setFrom(e.target.value)} disabled={report==='Balance sheet'}/></label><label>To<input type="date" value={to} min={from||undefined} onChange={e=>setTo(e.target.value)}/></label><button onClick={()=>safe(async()=>{await exportRows(report,reportData,'xlsx')})}><Download size={16}/>Excel</button><button onClick={()=>safe(async()=>{await exportRows(report,reportData,'csv')})}>CSV</button><button onClick={()=>safe(()=>printReport(report,reportData))}><Printer size={16}/>Print / PDF</button></div><div className="report-title"><h2>{report}</h2><p>{report==='Balance sheet'?'Cumulative book balances as of the selected end date.':'Amounts in PKR. Use the date range to inspect a period.'}</p>{report==='Stock report'||report==='Audit log'?<small>These records show current stock / recent audit entries; date filters apply to financial reports.</small>:null}</div>{reportData.length?<><DataTable headers={Object.keys(reportData[0])}>{reportVisible.map((r:Row,i:number)=><tr key={i}>{Object.values(r).map((v:any,j:number)=><td key={j}>{typeof v==='number'?money(v):String(v??'—')}</td>)}</tr>)}</DataTable><Pagination {...reportPagination}/></>:<Empty/>}<div className="info">Reports cover recorded transactions. Reconcile old supplier payments and add opening capital for a complete financial picture.</div></section>}
